/// The glyph called [name], resolving deprecated aliases.
///
/// Returns `null` for a name lucide 1.28.0 does not ship.
DsLucideGlyph? dsLucideLookup(String name) =>
    dsLucideByName[name] ?? dsLucideByName[dsLucideAliases[name] ?? ''];
